const data = $input.first().json.output || {};

const get = (k, fallback = "") => (data[k] ?? fallback);

function esc(s) {
  return String(s ?? "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;");
}

function ul(value) {
  if (!value) return "";
  const arr = Array.isArray(value) ? value : [value];
  const items = arr
    .map(x => String(x).trim())
    .filter(Boolean)
    .map(x => `<li>${esc(x)}</li>`)
    .join("");
  return items ? `<ul>${items}</ul>` : "";
}

const title = get("Title", "AI/Digital Tip");
const summary = get("Summary", "");
const potentialUsers = get("Example of users", []);
const useCase = get("Use Case", "");
const steps = get("Steps", []);
const promptExamples = get("Prompt Examples", []);
const tools = get("Tools", []);
const timeSaved = get("Estimated Time Saved", "");
const notes = get("Things to take note of", []);
const cta = get("cta", "");

const content =
  `<b>${esc(title)}</b><br><br>` +
  `${esc(summary)}<br><br>` +

  `<b>Potential Users</b>` +
  `${ul(potentialUsers)}<br>` +

  `<b>Use Case</b><br>` +
  `${esc(useCase)}<br><br>` +

  `<b>How to use</b>` +
  `${ul(steps)}<br>` +

  `<b>Prompt Examples</b>` +
  `${ul(promptExamples)}<br>` +

  `<b>Tools</b>` +
  `${ul(tools)}<br>` +

  `<b>Estimated Time Saved</b><br>` +
  `- ${esc(timeSaved)}<br><br>` +

  `<b>Notes</b>` +
  `${ul(notes)}<br>` +

  `<b>Recommendations</b><br>` +
  `${esc(cta)}`;

return [{ json: { ...$input.first().json, content } }];
